_INV_FREQ = {}

def _inv_freq(theta, device):
    key = (float(theta), str(device))
    if key not in _INV_FREQ:
        _INV_FREQ[key] = (1.0 / (theta ** (torch.arange(0, 64, 2, device=device).float() / 64))).contiguous()
    return _INV_FREQ[key]


